parameters.jsCode:
// 1. Obtención y parseo de datos
const inputItem = $input.first().json;
let rawData = inputItem.output || inputItem.text || inputItem;

if (typeof rawData === 'string') {
  try {
    const cleanJson = rawData.replace(/```json/gi, '').replace(/```/gi, '').trim();
    rawData = JSON.parse(cleanJson);
  } catch (e) {
    rawData = { texto_bruto: rawData };
  }
}

// 2. Extracción de sub-objetos
const docObj = rawData.documento || {};
const pacienteObj = rawData.paciente || {};
const profesionalObj = rawData.profesional || {};
const clinicoObj = rawData.clinico || {};
const metaObj = rawData.metadata_control || {};

const tipoDoc = String(docObj.tipo || rawData.tipo_documento || "Desconocido").trim();
const tipoLower = tipoDoc.toLowerCase();

// 3. DETECCIÓN BLINDADA DE IMAGEN Y DETERMINISMO
// Si la respuesta proviene de la rama de visión o contiene banderas de estudio de imagen
const esEstudioImagen = Boolean(
  clinicoObj.es_estudio_imagen === true ||
  tipoLower.includes("imagen") ||
  tipoLower.includes("radiograf") ||
  tipoLower.includes("ecograf") ||
  tipoLower.includes("tomograf") ||
  tipoLower.includes("laboratorio") ||
  tipoLower.includes("desconocido") // Si es imagen y no la identificó bien, se clasifica como estudio
);

const scoreConfianza = Number(docObj.confianza_clasificacion || rawData.confianza_clasificacion || 0.90);

// 4. LÓGICA DE REVISIÓN HUMANA
let requiereRevision = false;
let motivos = [];

if (metaObj.requiere_revision_humana === true || String(metaObj.requiere_revision_humana).toLowerCase() === "true") {
  requiereRevision = true;
  motivos.push("Declarado por IA: Documento o imagen ilegible / requiere revisión");
} else if (!esEstudioImagen) {
  // Solo los PDFs aplican estas reglas estrictas de datos faltantes
  if (tipoLower === "desconocido" || scoreConfianza < 0.60) {
    requiereRevision = true;
    motivos.push("Confianza baja o tipo de documento no identificado");
  }
  if (!pacienteObj.nombre_completo || String(pacienteObj.nombre_completo).toLowerCase() === "no claro") {
    requiereRevision = true;
    motivos.push("Nombre de paciente no claro o ilegible");
  }
}

// 5. Salida unificada
return {
  documento: {
    tipo: esEstudioImagen ? "Informe de Imagenología / Laboratorio" : tipoDoc,
    confianza_clasificacion: scoreConfianza
  },
  paciente: {
    nombre_completo: pacienteObj.nombre_completo || "No claro",
    identificacion: pacienteObj.identificacion || "Desconocido",
    edad: pacienteObj.edad || null
  },
  profesional: {
    nombre_completo: profesionalObj.nombre_completo || "No especificado",
    especialidad: profesionalObj.especialidad || "",
    matricula: profesionalObj.matricula || ""
  },
  clinico: {
    urgencia: Boolean(clinicoObj.urgencia === true || String(clinicoObj.urgencia).toLowerCase() === "true"),
    hipotesis_diagnostica: clinicoObj.hipotesis_diagnostica || "",
    medicamentos: clinicoObj.medicamentos || [],
    es_estudio_imagen: esEstudioImagen
  },
  metadata_control: {
    requiere_revision_humana: requiereRevision,
    motivos_revision: motivos,
    fecha_procesamiento: new Date().toISOString()
  }
};

// Obtener el elemento de entrada
const item = $input.first();

// Buscar la propiedad binaria (habitualmente 'data')
const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length === 0) {
  throw new Error("No se encontró ningún archivo binario en la entrada de imagen.");
}

const binaryPropertyName = binaryKeys[0];
const binaryData = item.binary[binaryPropertyName];

// Normalizar MIME Type para extensiones conflictivas como jfif
let mimeType = binaryData.mimeType || 'image/jpeg';
if (mimeType.includes('jfif') || binaryData.fileExtension === 'jfif') {
  mimeType = 'image/jpeg';
}

return {
  json: {
    ...item.json,
    es_imagen_normalizada: true,
    mime_type_detectado: mimeType
  },
  binary: {
    data: {
      ...binaryData,
      mimeType: mimeType,
      fileExtension: mimeType.split('/')[1] || 'jpg'
    }
  }
};

parameters.text:
Eres un asistente médico experto en la clasificación e inspección de imágenes de exámenes de laboratorio e imagenología médica.

Tu tarea principal es analizar la imagen recibida y generar UNICAMENTE un objeto JSON estructurado con la información leída.

Instrucciones de clasificación:
1. "documento.tipo": Si identificas una imagen médica, radiografía, ecografía, tomografía, informe de resonancia o examen de laboratorio, asigna SIEMPRE el tipo "Informe de Imagenología / Laboratorio". Solo asigna "Desconocido" si la imagen es completamente ajena a un contexto médico (ej. una foto aleatoria).
2. "clinico.es_estudio_imagen": Debe ser siempre true cuando la entrada sea una imagen o examen clínico.
3. "metadata_control.requiere_revision_humana": Debe ser false si logras ver los datos generales de la imagen médica. Solo asigna true si la imagen está completamente borracha, oscura o es ilegible.

Debes responder EXCLUSIVAMENTE en formato JSON plano con esta estructura exacta (sin markdown ni bloques de código extra):

{
  "documento": {
    "tipo": "Informe de Imagenología / Laboratorio",
    "confianza_clasificacion": 0.95
  },
  "paciente": {
    "nombre_completo": "Nombre encontrado o 'No claro'",
    "identificacion": "RUT/DNI encontrado o 'Desconocido'",
    "edad": null
  },
  "profesional": {
    "nombre_completo": "Nombre o 'No especificado'",
    "especialidad": "",
    "matricula": ""
  },
  "clinico": {
    "urgencia": false,
    "hipotesis_diagnostica": "Descripción breve del estudio o hallazgo principal",
    "medicamentos": [],
    "es_estudio_imagen": true
  },
  "metadata_control": {
    "requiere_revision_humana": false,
    "motivos_revision": []
  }
}
